import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    m = int(input[index + 1])
    index += 2
    edges = []
    for _ in range(m):
        a = int(input[index]) - 1
        b = int(input[index + 1]) - 1
        edges.append((a, b))
        index += 2

    graph = [[] for _ in range(n)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    visited = [False] * n
    color = [-1] * n

    def bfs(start):
        queue = deque([start])
        visited[start] = True
        color[start] = 0
        while queue:
            u = queue.popleft()
            for v in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    color[v] = 1 - color[u]
                    queue.append(v)
                elif color[v] == color[u]:
                    return False
        return True

    bipartite = True
    for i in range(n):
        if not visited[i]:
            if not bfs(i):
                bipartite = False

    if not bipartite:
        print(0, 1)
        return

    components = []
    visited = [False] * n

    def dfs(node, component):
        stack = [node]
        while stack:
            u = stack.pop()
            if not visited[u]:
                visited[u] = True
                component.append(u)
                for v in graph[u]:
                    if not visited[v]:
                        stack.append(v)

    for i in range(n):
        if not visited[i]:
            component = []
            dfs(i, component)
            components.append(component)

    t = len(components) - 1
    w = 1
    for i in range(1, len(components)):
        w *= len(components[i])

    print(t, w)

if __name__ == "__main__":
    main()
